package io.storyspace.api;
import io.storyspace.catalog.*;import io.storyspace.service.*;import org.springframework.web.bind.annotation.*;import java.util.Map;import java.util.UUID;
@RestController @RequestMapping("/api/media")public class MediaAccessController {private final CurrentAccount current;private final TitleRepository titles;private final SubscriptionService subscriptions;
 public MediaAccessController(CurrentAccount c,TitleRepository t,SubscriptionService s){current=c;titles=t;subscriptions=s;}
 @GetMapping("/{titleId}/preview")public Map<String,Object> preview(@PathVariable UUID titleId){Title t=titles.findById(titleId).orElseThrow(()->new IllegalArgumentException("Title not found"));return Map.of("titleId",t.getId(),"title",t.getName(),"previewUrl","https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4","contentType","video/mp4","previewOnly",true,"notice","Creative Commons sample footage, not the title's actual video.");}
 @GetMapping("/{titleId}/playback")public Map<String,Object> playback(@PathVariable UUID titleId){var account=current.require();Title t=titles.findById(titleId).orElseThrow(()->new IllegalArgumentException("Title not found"));if(!subscriptions.hasPaidAccess(account))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"A demo Plus subscription is required. This is not a payment.");return Map.of("titleId",t.getId(),"title",t.getName(),"status","NOT_AVAILABLE","message","Licensed media has not been connected. This endpoint is an access-control placeholder.");}
}